//! The synthetic records under `examples/` and the `sync-operation-log-merge` conformance
//! fixture are generated here from a fixed seed, so they carry real ids, wraps and
//! signatures and can be regenerated byte for byte:
//!
//! ```text
//! OPENLOGOS_WRITE_EXAMPLES=1 cargo test -p openlogos-sync --test examples
//! ```
//!
//! Without the variable the test reads the files, checks they equal what the seed produces,
//! verifies every signature and wrap against the roster, replays the fixture's delivery
//! orders and compares the merged state. It is skipped where `examples/` is absent (the nix
//! source filter).

use std::collections::BTreeMap;
use std::path::PathBuf;

use openlogos_sync::enrollment::{EnrollmentRequest, Roster};
use openlogos_sync::envelope::{
    Argon2Params, PayloadContext, SealedPayload, open_payload, seal_payload,
};
use openlogos_sync::keys::{DeviceId, DeviceSecrets, OpId, RecoverySecret, VaultId};
use openlogos_sync::log::{Change, Draft, OpLog, Operation, Outcome, State};
use openlogos_sync::recovery::RecoveryExport;
use rand_chacha::ChaCha20Rng;
use rand_core::SeedableRng as _;
use serde::{Deserialize, Serialize};
use serde_json::Value;

/// The `sync-operation` example: a batch as one device or hub hands it to another.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
struct Batch {
    schema_version: String,
    vault_id: VaultId,
    operations: Vec<Operation>,
    payloads: BTreeMap<OpId, SealedPayload>,
}

/// One delivery order of the fixture.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
struct Delivery {
    name: String,
    order: Vec<OpId>,
}

/// The conformance fixture of kind `sync-merge`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
struct MergeFixture {
    id: String,
    kind: String,
    description: String,
    license: String,
    roster: Roster,
    operations: Vec<Operation>,
    deliveries: Vec<Delivery>,
    expected_state: State,
    active_devices: Vec<DeviceId>,
    expected_compacted: Vec<String>,
    expected_state_after_compaction: State,
}

struct Built {
    roster: Roster,
    batch: Batch,
    export: RecoveryExport,
    fixture: MergeFixture,
}

const NOW: &str = "2026-10-28T09:00:00Z";

fn build() -> Built {
    let mut rng = ChaCha20Rng::from_seed(*b"openlogos-b021-examples-seed-001");
    let vault = VaultId::generate(&mut rng);
    let ipad = DeviceSecrets::generate(&mut rng);
    let phone = DeviceSecrets::generate(&mut rng);
    let laptop = DeviceSecrets::generate(&mut rng);
    let recovery = RecoverySecret::generate(&mut rng);
    let (mut roster, key1) = Roster::found(
        &mut rng,
        vault.clone(),
        &ipad,
        "Study iPad",
        &recovery.public_hex(),
        NOW,
    )
    .unwrap();
    roster
        .approve(
            &mut rng,
            &EnrollmentRequest::new(vault.clone(), &phone, "Phone", NOW),
            &ipad,
            NOW,
        )
        .unwrap();
    roster
        .approve(
            &mut rng,
            &EnrollmentRequest::new(vault.clone(), &laptop, "Old laptop", NOW),
            &ipad,
            NOW,
        )
        .unwrap();
    roster
        .link_principal("https://id.example.family", "a1b2c3", &ipad, NOW)
        .unwrap();

    // The log: the iPad writes a note with a sealed body, a highlight and a tag; the phone,
    // having seen the first body only, writes a concurrent body (a sibling); the laptop
    // deletes a second note the iPad made; the phone acknowledges the deletion.
    let mut log = OpLog::new(vault.clone());
    let mut payloads = BTreeMap::new();
    let mut ops = Vec::new();
    let mut make = |rng: &mut ChaCha20Rng,
                    log: &mut OpLog,
                    device: &DeviceSecrets,
                    change: Change,
                    parents: Option<Vec<OpId>>,
                    body: Option<&[u8]>,
                    roster: &Roster| {
        let parents = parents.unwrap_or_else(|| log.heads());
        let seq = log.next_sequence(&device.device_id());
        let context = PayloadContext {
            vault_id: &vault,
            device_id: &device.device_id(),
            device_sequence: seq,
        };
        let sealed = body.map(|b| seal_payload(rng, &key1, 1, &context, b).unwrap());
        let op = Draft {
            vault_id: vault.clone(),
            device_sequence: seq,
            parents,
            key_epoch: 1,
            change,
            payload_hash: sealed.as_ref().map(|s| s.hash().unwrap()),
        }
        .sign(device);
        assert!(matches!(
            log.apply(op.clone(), roster),
            Ok(Outcome::Applied { .. })
        ));
        if let Some(s) = sealed {
            payloads.insert(op.op_id.clone(), s);
        }
        ops.push(op.clone());
        op
    };
    let note = |n: u32| Change::NoteBody {
        note_id: format!("note-john-3-16-{n:02}"),
    };
    let body1 = make(
        &mut rng,
        &mut log,
        &ipad,
        note(1),
        Some(vec![]),
        Some(b"God so loved: agape, not eros."),
        &roster,
    );
    let hl = make(
        &mut rng,
        &mut log,
        &ipad,
        Change::HighlightAdd {
            highlight_id: "hl-john-3-16-loved".to_owned(),
        },
        None,
        Some(br#"{"anchor":"bsb:043003016004-043003016007","style":"amber"}"#),
        &roster,
    );
    let _tag = make(
        &mut rng,
        &mut log,
        &ipad,
        Change::TagAdd {
            entity_id: "note-john-3-16-01".to_owned(),
            tag_id: "tag-love".to_owned(),
        },
        None,
        None,
        &roster,
    );
    let body1_ipad_edit = make(
        &mut rng,
        &mut log,
        &ipad,
        note(1),
        None,
        Some(b"God so loved: agape, not eros. Cf. 1 John 4:9."),
        &roster,
    );
    // The phone saw only body1 (and the highlight), not the later iPad edit: a sibling.
    let body1_phone = make(
        &mut rng,
        &mut log,
        &phone,
        note(1),
        Some(vec![body1.op_id.clone(), hl.op_id.clone()]),
        Some(b"God so loved (phone draft)."),
        &roster,
    );
    let note2 = make(
        &mut rng,
        &mut log,
        &ipad,
        note(2),
        None,
        Some(b"scratch"),
        &roster,
    );
    let tomb = make(
        &mut rng,
        &mut log,
        &laptop,
        Change::Tombstone {
            entity_id: "note-john-3-16-02".to_owned(),
        },
        Some(vec![note2.op_id.clone()]),
        None,
        &roster,
    );
    let _ack = make(
        &mut rng,
        &mut log,
        &phone,
        Change::TombstoneAck {
            entity_id: "note-john-3-16-02".to_owned(),
            tombstone: tomb.op_id.clone(),
        },
        None,
        None,
        &roster,
    );
    let _ = (body1_ipad_edit, body1_phone);
    drop(make);

    // Now the laptop is lost: revoked after its one operation; the key rotates to epoch 2.
    roster
        .revoke(&mut rng, &laptop.device_id(), &ipad, 1, "lost", NOW)
        .unwrap();
    roster.verify().unwrap();

    let export = RecoveryExport::create(
        &mut rng,
        &roster,
        &recovery,
        b"example passphrase",
        Argon2Params::default(),
        NOW,
    )
    .unwrap();

    let expected_state = log.materialize();
    let mut forward = ops.iter().map(|o| o.op_id.clone()).collect::<Vec<_>>();
    let reverse: Vec<OpId> = forward.iter().rev().cloned().collect();
    let mut interleaved: Vec<OpId> = Vec::new();
    for i in 0..forward.len().div_ceil(2) {
        interleaved.push(forward[i].clone());
        if let Some(late) = forward.get(forward.len() - 1 - i)
            && !interleaved.contains(late)
        {
            interleaved.push(late.clone());
        }
    }
    let mut with_replays = forward.clone();
    with_replays.insert(2, forward[0].clone());
    with_replays.push(forward[3].clone());
    forward.dedup();
    // Compaction: the iPad acknowledges too, then every active device (iPad, phone) has.
    let active = roster.active_devices();
    let mut compaction_log = log.clone();
    let ack_ipad = Draft {
        vault_id: vault.clone(),
        device_sequence: compaction_log.next_sequence(&ipad.device_id()),
        parents: compaction_log.heads(),
        key_epoch: 2,
        change: Change::TombstoneAck {
            entity_id: "note-john-3-16-02".to_owned(),
            tombstone: tomb.op_id.clone(),
        },
        payload_hash: None,
    }
    .sign(&ipad);
    compaction_log.apply(ack_ipad.clone(), &roster).unwrap();
    ops.push(ack_ipad.clone());
    let expected_compacted = compaction_log.compact(&active);
    let expected_state_after_compaction = compaction_log.materialize();

    let fixture = MergeFixture {
        id: "sync-operation-log-merge".to_owned(),
        kind: "sync-merge".to_owned(),
        description: "Nine signed operations of three devices (one revoked after its tombstone) delivered in four orders, with replays; every order must produce the same merged state: one note with two sibling bodies, one highlight, one tag, one deleted note. After the remaining active devices acknowledge, compaction drops the deleted note's history without changing the state. Keys, ids and signatures are real (seed in crates/sync/tests/examples.rs); the note bodies are fixture text.".to_owned(),
        license: "CC0 (fixture text written for this fixture; no scripture quoted)".to_owned(),
        roster: roster.clone(),
        operations: ops.clone(),
        deliveries: vec![
            Delivery {
                name: "forward".to_owned(),
                order: forward.clone(),
            },
            Delivery {
                name: "reverse".to_owned(),
                order: reverse,
            },
            Delivery {
                name: "interleaved".to_owned(),
                order: interleaved,
            },
            Delivery {
                name: "with_replays".to_owned(),
                order: with_replays,
            },
        ],
        expected_state,
        active_devices: active,
        expected_compacted,
        expected_state_after_compaction,
    };
    let batch = Batch {
        schema_version: "1.0".to_owned(),
        vault_id: vault,
        operations: ops[..ops.len() - 1].to_vec(),
        payloads,
    };
    Built {
        roster,
        batch,
        export,
        fixture,
    }
}

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn targets(built: &Built) -> Vec<(PathBuf, Value)> {
    vec![
        (
            root().join("examples/device-enrollment.json"),
            serde_json::to_value(&built.roster).unwrap(),
        ),
        (
            root().join("examples/sync-operation.json"),
            serde_json::to_value(&built.batch).unwrap(),
        ),
        (
            root().join("examples/recovery-export.json"),
            serde_json::to_value(&built.export).unwrap(),
        ),
        (
            root().join("crates/conformance/fixtures/sync-operation-log-merge.json"),
            serde_json::to_value(&built.fixture).unwrap(),
        ),
    ]
}

#[test]
fn examples_and_fixture_are_what_the_seed_produces() {
    let built = build();
    if std::env::var_os("OPENLOGOS_WRITE_EXAMPLES").is_some() {
        for (path, value) in targets(&built) {
            std::fs::write(&path, serde_json::to_string_pretty(&value).unwrap() + "\n").unwrap();
        }
    }
    if !root().join("examples").is_dir() {
        eprintln!("examples/ absent: skipping file comparison");
        return;
    }
    for (path, value) in targets(&built) {
        let text =
            std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
        let on_disk: Value = serde_json::from_str(&text).unwrap();
        assert_eq!(
            on_disk,
            value,
            "{} differs from the seed's output",
            path.display()
        );
    }
}

#[test]
fn the_records_verify_and_the_fixture_converges() {
    let built = build();
    built.roster.verify().unwrap();
    built.export.check().unwrap();
    assert_eq!(built.roster.key_epoch, 2);
    assert_eq!(built.roster.active_devices().len(), 2);
    assert!(built.roster.devices[2].revocation.is_some());

    // Every batch operation verifies against the roster and every payload hash matches.
    let mut log = OpLog::new(built.batch.vault_id.clone());
    for op in &built.batch.operations {
        assert!(
            matches!(
                log.apply(op.clone(), &built.roster),
                Ok(Outcome::Applied { .. })
            ),
            "{}",
            op.op_id
        );
        if let Some(hash) = &op.payload_hash {
            assert_eq!(&built.batch.payloads[&op.op_id].hash().unwrap(), hash);
        }
    }
    // The export opens and its key reads a payload.
    let (recovered, key) = built.export.open(b"example passphrase").unwrap();
    assert_eq!(
        recovered.public_hex(),
        built.roster.recovery.recovery_public
    );
    let first = &built.batch.operations[0];
    let context = PayloadContext {
        vault_id: &built.batch.vault_id,
        device_id: &first.device_id,
        device_sequence: first.device_sequence,
    };
    assert!(
        open_payload(&key, &context, &built.batch.payloads[&first.op_id]).is_err(),
        "epoch 2 key does not open an epoch 1 payload"
    );

    // The fixture: every delivery order converges on the expected state.
    let f = &built.fixture;
    let by_id: BTreeMap<&OpId, &Operation> = f.operations.iter().map(|o| (&o.op_id, o)).collect();
    for delivery in &f.deliveries {
        let mut log = OpLog::new(f.roster.vault_id.clone());
        for id in &delivery.order {
            log.apply(by_id[id].clone(), &f.roster).unwrap();
        }
        assert!(log.pending().is_empty(), "{}", delivery.name);
        assert_eq!(log.materialize(), f.expected_state, "{}", delivery.name);
    }
    assert_eq!(
        f.expected_state.notes["note-john-3-16-01"].len(),
        2,
        "two sibling bodies"
    );
    assert!(f.expected_state.deleted.contains("note-john-3-16-02"));
    let mut log = OpLog::new(f.roster.vault_id.clone());
    for op in &f.operations {
        log.apply(op.clone(), &f.roster).unwrap();
    }
    assert_eq!(log.compact(&f.active_devices), f.expected_compacted);
    assert_eq!(log.materialize(), f.expected_state_after_compaction);
    assert_eq!(
        f.expected_state_after_compaction, f.expected_state,
        "compaction changes no state"
    );
    assert!(
        log.operations()
            .all(|op| op.change.entity_id() != "note-john-3-16-02")
    );
}
